settings.custom_liquid:
{% assign ft_breadcrumb_parent = collections['rubber-fenders'] %}
{% assign ft_breadcrumb_title = ft_breadcrumb_parent.title | default: 'Rubber fenders' %}
{% assign ft_breadcrumb_path = ft_breadcrumb_parent.url %}
{% if ft_breadcrumb_path == blank %}{% assign ft_breadcrumb_path = routes.root_url | append: 'collections/rubber-fenders' %}{% endif %}
{% assign ft_breadcrumb_parent_url = request.host | prepend: 'https://' | append: ft_breadcrumb_path %}
{% assign ft_breadcrumb_current_url = canonical_url | split: '?' | first %}
{% assign ft_breadcrumb_current_title = collection.title %}
{% if theme.role == 'development' and request.locale.iso_code != 'da' and request.locale.iso_code != 'en' and request.locale.iso_code != 'de' and request.locale.iso_code != 'es' and request.locale.iso_code != 'fr' and request.locale.iso_code != 'it' and request.locale.iso_code != 'nl' and request.locale.iso_code != 'nb' and request.locale.iso_code != 'sv' %}
  {% assign ft_breadcrumb_legacy = collections['yokohama-type-pneumatic-fenders'] %}
  {% assign ft_breadcrumb_current_title = ft_breadcrumb_legacy.title | default: ft_breadcrumb_current_title %}
{% endif %}
{% assign ft_breadcrumb_label = 'fendertec_yokohama.navigation.breadcrumb' | t %}
<nav class="ft-yoko-breadcrumbs page-width" aria-label="{{ ft_breadcrumb_label | escape }}">
  <ol role="list">
    <li><a href="{{ ft_breadcrumb_path | escape }}">{{ ft_breadcrumb_title | escape }}</a></li>
    <li><span class="ft-breadcrumb-chevron" aria-hidden="true"></span><span aria-current="page">{{ ft_breadcrumb_current_title | escape }}</span></li>
  </ol>
</nav>
<script type="application/ld+json">
{
  "@context":"https://schema.org",
  "@type":"BreadcrumbList",
  "itemListElement":[
    {"@type":"ListItem","position":1,"name":{{ ft_breadcrumb_title | json }},"item":{{ ft_breadcrumb_parent_url | json }}},
    {"@type":"ListItem","position":2,"name":{{ ft_breadcrumb_current_title | json }},"item":{{ ft_breadcrumb_current_url | json }}}
  ]
}
</script>
<style>
#MainContent .ft-yoko-breadcrumbs{padding-top:var(--ft-section-gap,48px);padding-bottom:16px;color:var(--ft-brand-red)}
.ft-yoko-breadcrumbs ol{display:flex;flex-wrap:wrap;align-items:baseline;gap:6px 12px;margin:0;padding:0;list-style:none}
.ft-yoko-breadcrumbs li{display:flex;align-items:baseline;gap:12px;min-width:0}
.ft-yoko-breadcrumbs a{color:inherit;text-decoration:none}
.ft-yoko-breadcrumbs a:hover{text-decoration:underline;text-underline-offset:3px}
.ft-yoko-breadcrumbs [aria-current="page"]{overflow-wrap:anywhere}
#MainContent #shopify-section-{{ section.id | replace: 'custom_liquid_zbEwzF', 'banner' }}{margin-top:0}
</style>

<style>#MainContent .collection-hero__title{display:none}</style>

<style>
#MainContent .ft-yoko-breadcrumbs{padding-top:0;padding-bottom:24px}
#MainContent #shopify-section-{{ section.id | replace: 'custom_liquid_zbEwzF', 'banner' }}{margin-top:var(--ft-section-gap,48px)}
</style>
